<?php
namespace App\\Services;
use App\\Models\\SocialPost;use App\\Models\\PublishingHandoff;use Illuminate\\Support\\Facades\\DB;use Illuminate\\Support\\Facades\\File;use RuntimeException;
final class PublishingService {public function __construct(private ContentFingerprint $fingerprint){}public function handoff(SocialPost $post):PublishingHandoff{return DB::transaction(function()use($post){$p=SocialPost::query()->lockForUpdate()->findOrFail($post->id);if($p->status!=='approved')throw new RuntimeException('Explicit approval is required.');if(blank($p->media_reference))throw new RuntimeException('Media reference is missing.');$approval=$p->approvals()->where('version',$p->version)->latest('id')->first();if(!$approval||!hash_equals($approval->fingerprint,$this->fingerprint->for($p)))throw new RuntimeException('Approval is missing or stale; review the current version again.');$key=hash('sha256',$p->id.'|'.$approval->fingerprint);$existing=PublishingHandoff::where('idempotency_key',$key)->first();if($existing)return $existing;$payload=['post_id'=>$p->id,'idea_id'=>$p->idea_id,'version'=>$p->version,'channels'=>$p->channels,'scheduled_at'=>$p->scheduled_at->toISOString(),'text'=>$p->body,'media_reference'=>$p->media_reference,'approval_fingerprint'=>$approval->fingerprint,'idempotency_key'=>$key,'mode'=>'SIMULATED — no external publication'];$record=PublishingHandoff::create(['social_post_id'=>$p->id,'idempotency_key'=>$key,'payload'=>$payload,'status'=>'handed_over','handed_off_at'=>now()]);$p->update(['status'=>'handed_over']);File::ensureDirectoryExists(storage_path('app/publishing'));File::put(storage_path('app/publishing/handoff-'.$record->id.'.json'),json_encode($payload,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));return $record;});}}